PREFIX ml: <http://www.semanticweb.org/mnd14/ml/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?entity ?entity_type ?label
WHERE {
    {
        ?entity rdfs:subClassOf+ ml:MachineLearningModel .
        BIND("Class" AS ?entity_type)
        OPTIONAL { ?entity rdfs:label ?label }
        FILTER(?entity != <http://www.w3.org/2002/07/owl#Nothing>)
    }
    UNION
    {
        ?entity rdf:type/rdfs:subClassOf* ml:MachineLearningModel .
        OPTIONAL { ?entity rdf:type/rdfs:label ?entity_type }
        OPTIONAL { ?entity rdfs:label ?label }
        FILTER(?entity != <http://www.w3.org/2002/07/owl#Nothing>)
    }
}
LIMIT 100

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?ns WHERE {
  { ?s a/rdfs:subClassOf* ?o . }
  UNION
  { ?s ?p ?o . }
  FILTER(isIRI(?ns) || isURI(?ns))
  BIND(STR(?s) AS ?s_str)
  BIND(STR(?p) AS ?p_str)
  BIND(STR(?o) AS ?o_str)
  {
    SELECT DISTINCT ?ns WHERE {
      { BIND(IRI(REPLACE(STR(?s), "^([^#/]+[#/]).*$", "$1")) AS ?ns) }
      UNION
      { BIND(IRI(REPLACE(STR(?p), "^([^#/]+[#/]).*$", "$1")) AS ?ns) }
      UNION
      { BIND(IRI(REPLACE(STR(?o), "^([^#/]+[#/]).*$", "$1")) AS ?ns) }
    }
  }
} LIMIT 100
